/**
 * On the development server, staff can preview theme presets at runtime. Nuxt prepares the previews during
 * configuration, like
 * `theme-output.ts`: the browser receives strings and JSON, never the engine.
 *
 * A personal theme replaces the installation theme; it does not sit on top of it. The installation's CSS (generated by
 * `themeOutput`) is unlayered and beats Nuxt UI's `@layer theme`, so every token the installation sets and the chosen
 * theme does not is reset here:
 * - unlayered tokens with `revert-layer` (back to the library default or the colours plugin, both `@layer theme`);
 * - `@theme` keys with Tailwind's default (the installation's own `@theme` sits in `@layer theme` too, so
 *   `revert-layer` would land on it);
 * - `@layer base` rules with `inherit` (body, headings) or `revert-layer` (the html font size).
 * The blocks keep the installation's specificity, (0,1,0), so the tenant's house colour (`html:root`, (0,1,1);
 * `html.dark:root`, (0,2,1)) stays on top; they rely on coming after the installation CSS.
 */

import { presets } from './engine/presets';
import { offeredPresets } from './installation-theme';
import { themeOutput, type ThemeOutput } from './theme-output';

/** Also in the staff layer's `staff-theme-preview-runtime.ts` (the browser must not import this file). */
export const STAFF_THEME_ATTRIBUTE = 'data-staff-theme';
export const STAFF_THEMES_TEMPLATE = 'beantragt-staff-themes.ts';

/** The light keys of an engine theme as the cascade sees them, block by block. */
export interface ThemeBlocks {
    /** `@theme` and `@theme static`: compiled by Tailwind into `@layer theme`. */
    theme: Map<string, string>
    /** `:root` and `:root, .light` in order: unlayered, in both modes. */
    light: Map<string, string>
    /** `.dark`: unlayered, dark mode only. */
    dark: Map<string, string>
    /** `@layer base { html { … } }` */
    html: Map<string, string>
    /** `@layer base { body { … } }` */
    body: Map<string, string>
    /** `@layer base { h1, … h6 { … } }` */
    headings: Map<string, string>
}

export interface StaffPreviewTheme {
    id: string
    name: string
    css: string
    ui: Record<string, unknown>
    fontFamilies: string[]
}

const HEADINGS = 'h1, h2, h3, h4, h5, h6';

/** Top-level `selector { body }` blocks of a stylesheet, comments removed. */
function topLevelBlocks(css: string): Array<{ selector: string, body: string }> {
    const text = css.replace(/\/\*[\s\S]*?\*\//gu, '');
    const blocks: Array<{ selector: string, body: string }> = [];
    let depth = 0;
    let start = 0;
    let selectorStart = 0;
    for (let index = 0; index < text.length; index += 1) {
        const char = text[index];
        if (char === '{') {
            if (depth === 0) {
                start = index + 1;
                blocks.push({ selector: text.slice(selectorStart, index).trim(), body: '' });
            }
            depth += 1;
        } else if (char === '}') {
            depth -= 1;
            if (depth === 0) {
                blocks[blocks.length - 1]!.body = text.slice(start, index);
                selectorStart = index + 1;
            }
        }
    }
    if (depth !== 0) throw new Error('staff theme preview: unbalanced braces in the theme CSS');
    return blocks;
}

function declarations(body: string): Map<string, string> {
    const map = new Map<string, string>();
    for (const part of body.split(';')) {
        const colon = part.indexOf(':');
        if (colon < 0) continue;
        map.set(part.slice(0, colon).trim(), part.slice(colon + 1).trim().replace(/\s+/gu, ' '));
    }
    return map;
}

/** The engine's CSS (`themeOutput(doc).css`) as blocks; throws on a block it does not know, so a changed engine shows. */
export function parseThemeCSS(css: string): ThemeBlocks {
    const blocks: ThemeBlocks = { theme: new Map(), light: new Map(), dark: new Map(), html: new Map(), body: new Map(), headings: new Map() };
    const into = (target: Map<string, string>, body: string) => {
        for (const [key, value] of declarations(body)) target.set(key, value);
    };
    for (const { selector, body } of topLevelBlocks(css)) {
        if (selector === '@theme' || selector === '@theme static') into(blocks.theme, body);
        else if (selector === ':root' || selector === ':root, .light') into(blocks.light, body);
        else if (selector === '.dark') into(blocks.dark, body);
        else if (selector === '@layer base') {
            for (const inner of topLevelBlocks(body)) {
                if (inner.selector === 'html') into(blocks.html, inner.body);
                else if (inner.selector === 'body') into(blocks.body, inner.body);
                else if (inner.selector === HEADINGS) into(blocks.headings, inner.body);
                else throw new Error(`staff theme preview: unknown rule "${inner.selector}" in @layer base`);
            }
        } else {
            throw new Error(`staff theme preview: unknown block "${selector}" in the theme CSS`);
        }
    }
    return blocks;
}

/** Tailwind's `@theme default` values (`tailwindcss/theme.css`), for the `@theme` keys a theme may leave out. */
export function parseTailwindThemeDefaults(themeCss: string): Map<string, string> {
    const block = topLevelBlocks(themeCss).find(entry => entry.selector === '@theme default');
    if (!block) throw new Error('staff theme preview: no @theme default block in tailwindcss/theme.css');
    return declarations(block.body);
}

function rule(selector: string, entries: Iterable<[string, string]>, indent = ''): string {
    const lines = [...entries].map(([key, value]) => `${indent}  ${key}: ${value};`);
    return lines.length ? `${indent}${selector} {\n${lines.join('\n')}\n${indent}}` : '';
}

/** With every key of `installation` that `personal` lacks reset to `reset(key)`. */
function withResets(personal: Map<string, string>, installation: Map<string, string>, reset: (key: string) => string, skip: (key: string) => boolean = () => false): Map<string, string> {
    const result = new Map(personal);
    for (const key of installation.keys()) {
        if (!result.has(key) && !skip(key)) result.set(key, reset(key));
    }
    return result;
}

/**
 * The runtime stylesheet of a personal theme: the engine CSS of `personalCss` rewritten to plain declarations under
 * `[data-staff-theme="<id>"]`, with resets for what `installationCss` sets.
 */
export function staffThemeCSS(id: string, personalCss: string, installationCss: string, tailwindDefaults: Map<string, string>): string {
    if (!/^[a-z0-9-]+$/u.test(id)) throw new Error(`staff theme preview: unexpected theme id "${id}"`);
    const personal = parseThemeCSS(personalCss);
    const installation = parseThemeCSS(installationCss);
    const scope = `[${STAFF_THEME_ATTRIBUTE}="${id}"]`;

    const themeKeys = withResets(personal.theme, installation.theme, (key) => {
        const value = tailwindDefaults.get(key);
        if (value === undefined) throw new Error(`staff theme preview: no Tailwind default for ${key}, which the installation sets`);
        return value;
    }, key => key.startsWith('--color-'));
    const light = new Map([...themeKeys, ...withResets(personal.light, installation.light, () => 'revert-layer')]);
    // A dark key the theme sets in light only keeps the light value (unlayered, as without the installation).
    const dark = withResets(personal.dark, installation.dark, () => 'revert-layer', key => personal.light.has(key));
    const html = withResets(personal.html, installation.html, () => 'revert-layer');
    const body = withResets(personal.body, installation.body, () => 'inherit');
    const headings = withResets(personal.headings, installation.headings, () => 'inherit');

    const base = [
        rule(`html:where(${scope})`, html, '  '),
        rule(`:where(${scope}) body`, body, '  '),
        rule(`:where(${scope}) :is(${HEADINGS})`, headings, '  ')
    ].filter(Boolean);
    return [
        rule(`:root:where(${scope})`, light),
        rule(`:where(${scope}).dark`, dark),
        base.length ? `@layer base {\n${base.join('\n')}\n}` : ''
    ].filter(Boolean).join('\n\n');
}

function isPlainObject(value: unknown): value is Record<string, unknown> {
    return typeof value === 'object' && value !== null && !Array.isArray(value);
}

/** `defu(primary, base)`: what Nuxt does with the theme's app config and the inline one (arrays concatenated). */
export function mergeDefaults(primary: Record<string, unknown>, base: Record<string, unknown>): Record<string, unknown> {
    const result: Record<string, unknown> = { ...base };
    for (const [key, value] of Object.entries(primary)) {
        if (value === undefined) continue;
        const fallback = base[key];
        if (Array.isArray(value) && Array.isArray(fallback)) result[key] = [...value, ...fallback];
        else if (isPlainObject(value) && isPlainObject(fallback)) result[key] = mergeDefaults(value, fallback);
        else result[key] = value;
    }
    return result;
}

/**
 * Every offered preset as the mock switches to it: its stylesheet against the installation's, and its app config
 * merged with the inline one (`nuxt.options.appConfig`, where the Nuxt UI module puts colours, icons, prefix), which
 * is what Nuxt builds for `NUXT_UI_THEME=<id>` (`app/app.config.ts` is empty). The preset "Default" is shown as
 * "Nuxt UI", so it does not read twice next to "Standard" (the installation's theme).
 */
export function staffPreviewThemes(installation: ThemeOutput, inlineUi: Record<string, unknown>, tailwindDefaults: Map<string, string>): StaffPreviewTheme[] {
    return offeredPresets().map((id) => {
        const preset = presets.find(entry => entry.id === id)!;
        const output = themeOutput(preset.doc);
        return {
            id,
            name: id === 'default' ? 'Nuxt UI' : preset.name,
            css: staffThemeCSS(id, output.css, installation.css, tailwindDefaults),
            ui: mergeDefaults((output.config.ui ?? {}) as Record<string, unknown>, inlineUi),
            fontFamilies: output.fontFamilies
        };
    });
}

/** The template's source: the themes on the development server, an empty list in every other build. */
export function staffThemesTemplate(themes: StaffPreviewTheme[]): string {
    return [
        '// Generated theme previews for the development server. Production builds export an empty list. Do not edit.',
        'const themes: Array<{ id: string, name: string, css: string, ui: Record<string, unknown>, fontFamilies: string[] }> = '
        + `${JSON.stringify(themes)};`,
        'export default themes;',
        ''
    ].join('\n');
}
